import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] inputLine = br.readLine().split(" ");
        int n = Integer.parseInt(inputLine[0]);
        int mod = Integer.parseInt(inputLine[1]);

        List<Long> dpList = new ArrayList<>();
        dpList.add(0L);
        dpList.add(1L);
        long total = 1L;

        for (int i = 2; i <= n; i++) {
            int maxCheck = (int) Math.sqrt(i) + 1;
            long currentTotal = total;

            for (int f = 2; f < maxCheck; f++) {
                currentTotal = sumMod(currentTotal, dpList.get(i / f), mod);
            }

            int boundaryValue = i;
            for (int j = 1; j <= i / maxCheck; j++) {
                int nextValue = i / (j + 1);
                long product = productMod(boundaryValue - nextValue, dpList.get(j), mod);
                currentTotal = sumMod(currentTotal, product, mod);
                boundaryValue = nextValue;
            }

            total = sumMod(total, currentTotal, mod);
            dpList.add(currentTotal);
        }

        System.out.println(dpList.get(dpList.size() - 1));
    }

    private static long sumMod(long a, long b, int mod) {
        return (a + b) % mod;
    }

    private static long productMod(long a, long b, int mod) {
        return (a * b) % mod;
    }
}
